const features = $('Source 1').first().json.features;

// Initialize band summary object
const bands = {
  minor: { event_count: 0, max_magnitude: -Infinity, max_depth_km: -Infinity },
  moderate: { event_count: 0, max_magnitude: -Infinity, max_depth_km: -Infinity },
  major: { event_count: 0, max_magnitude: -Infinity, max_depth_km: -Infinity }
};

// Process each feature
features.forEach(feature => {
  const mag = feature.properties.mag;
  const depth = feature.geometry.coordinates[2];

  let band;
  if (mag < 4.0) {
    band = 'minor';
  } else if (mag >= 4.0 && mag < 5.0) {
    band = 'moderate';
  } else {
    band = 'major';
  }

  bands[band].event_count++;
  bands[band].max_magnitude = Math.max(bands[band].max_magnitude, mag);
  bands[band].max_depth_km = Math.max(bands[band].max_depth_km, depth);
});

// Build output records
const records = [];
for (const [bandName, bandData] of Object.entries(bands)) {
  if (bandData.event_count > 0) {
    records.push({
      magnitude_band: bandName,
      event_count: bandData.event_count,
      max_magnitude: bandData.max_magnitude,
      max_depth_km: bandData.max_depth_km
    });
  }
}

return [{ json: { records } }];
